#include <string>
#include <vector>

int stackBytes(const std::vector<int>& argumentSizes)
{
    int total{ 0 };
    for (int size : argumentSizes)
    {
        const int at_least_4{ size < 4 ? 4 : size };
        total += (at_least_4 + 3) / 4 * 4;
    }
    return total;
}

std::string exportName32(const std::string& name, const std::string& convention, const std::vector<int>& argumentSizes)
{
    const std::string n{ std::to_string(stackBytes(argumentSizes)) };
    if (convention == "cdecl") return "_" + name;
    if (convention == "stdcall") return "_" + name + "@" + n;
    if (convention == "fastcall") return "@" + name + "@" + n;
    return name;
}

unitTests:
TEST("stdcall two ints") { CHECK_EQ(exportName32("area", "stdcall", { 4, 4 }), std::string("_area@8")); }
TEST("an int and a double") { CHECK_EQ(exportName32("f", "stdcall", { 4, 8 }), std::string("_f@12")); }
TEST("small arguments take 4 bytes") { CHECK_EQ(exportName32("g", "stdcall", { 1, 2 }), std::string("_g@8")); CHECK_EQ(stackBytes({ 1 }), 4); }
TEST("odd sizes round up") { CHECK_EQ(stackBytes({ 6 }), 8); CHECK_EQ(stackBytes({ 12, 1 }), 16); }
TEST("cdecl") { CHECK_EQ(exportName32("stackHeight", "cdecl", { 4, 4 }), std::string("_stackHeight")); }
TEST("fastcall") { CHECK_EQ(exportName32("h", "fastcall", { 4, 4, 4 }), std::string("@h@12")); }
TEST("no arguments") { CHECK_EQ(exportName32("tick", "stdcall", {}), std::string("_tick@0")); }
TEST("unknown convention") { CHECK_EQ(exportName32("x", "vectorcall", { 4 }), std::string("x")); }

